export function verse(n: number): string[] {
  if (Number.isNaN(n) || n < 1 || n > 12) {
    throw new Error("Invalid verse number");
  }

  const data: { subject: string; verb: string }[] = [
    { subject: "the house that Jack built", verb: "" },
    { subject: "the malt", verb: "lay in" },
    { subject: "the rat", verb: "ate" },
    { subject: "the cat", verb: "killed" },
    { subject: "the dog", verb: "worried" },
    { subject: "the cow with the crumpled horn", verb: "tossed" },
    { subject: "the maiden all forlorn", verb: "milked" },
    { subject: "the man all tattered and torn", verb: "kissed" },
    { subject: "the priest all shaven and shorn", verb: "married" },
    { subject: "the rooster that crowed in the morn", verb: "woke" },
    { subject: "the farmer sowing his corn", verb: "kept" },
    { subject: "the horse and the hound and the horn", verb: "belonged to" },
  ];

  const lines: string[] = [];
  for (let i = n - 1; i >= 0; i--) {
    if (i === 0) {
      lines.push(`This is ${data[i].subject}.`);
    } else {
      lines.push(`This is ${data[i].subject}`);
      lines.push(`that ${data[i].verb} ${data[i - 1].subject}`);
    }
  }

  return lines;
}

export function verses(start: number, end: number): string[] {
  if (Number.isNaN(start) || Number.isNaN(end) || start < 1 || end > 12 || start > end) {
    throw new Error("Invalid verse range");
  }

  const result: string[] = [];
  for (let i = start; i <= end; i++) {
    result.push(...verse(i));
    if (i < end) {
      result.push("");
    }
  }

  return result;
}
